import 'dart:convert';import 'package:file_picker/file_picker.dart';import 'package:share_plus/share_plus.dart';import '../data/astro_repository.dart';
class BackupService{Future<void> exportBackup()async{final data=jsonEncode(await AstroRepository.instance.exportAll());await SharePlus.instance.share(ShareParams(text:data,subject:'AstroDaily local backup JSON'));}
Future<void> importBackup({required bool replace})async{final result=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['json'],withData:true);if(result==null)return;final bytes=result.files.single.bytes;if(bytes==null)throw const FormatException('Cannot read backup file.');if(bytes.length>5*1024*1024)throw const FormatException('Backup exceeds 5 MB.');final value=jsonDecode(utf8.decode(bytes));if(value is! Map<String,dynamic>)throw const FormatException('Invalid backup JSON.');await AstroRepository.instance.importAll(value,replace:replace);}}
